\def\DE{\par\egroup\shipout\box\dispbox}
\def\IB{\setbox\dispbox\hbox\bgroup\special{dvisvgm:raw <desc>base={?y}</desc>}}
\def\IE{\egroup\shipout\box\dispbox}
\def\DM#1{\immediate\write16{@@DISPLAY #1}}
