1	// Checks the built reader in Chromium at a phone's width, light and dark:
2	//   python3 -m http.server 8765 --directory <a folder that holds fortress/ -> docs/> &
3	//   node explorations/coordinator/tools/spec-html/check.js [URL of the reader] [folder for the two screenshots]
4	// It needs Playwright (NODE_PATH, or /opt/node-tools/node_modules). README.md says what it covers.
5	let pw;
6	try { pw = require('playwright'); } catch (e) { pw = require('/opt/node-tools/node_modules/playwright'); }
7	const { chromium } = pw;
8	const fs = require('fs');
9	const os = require('os');
10	const path = require('path');
11	const U = process.argv[2] || 'http://localhost:8765/fortress/specification/';
12	const SHOTS = process.argv[3] || '/tmp';
13	const PUBLIC = 'https://palimondo.github.io/fortress/specification/';
14	let failed = 0;
15	const ok = (c, m) => { if (!c) failed++; console.log((c ? 'PASS ' : 'FAIL ') + m); };
16	(async () => {
17	  const b = await chromium.launch();
18	  const c = await b.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, hasTouch: true, colorScheme: 'light', acceptDownloads: true, permissions: ['clipboard-read', 'clipboard-write'] });
19	  const p = await c.newPage();
20	  const ext = [];
21	  p.on('request', r => { if (!r.url().startsWith(U)) ext.push(r.url()); });
22	  p.on('pageerror', e => console.log('PAGEERROR', e.message));
23	  p.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
24	  // overflow in every page, light and dark
25	  for (const scheme of ['light', 'dark']) {
26	    await p.emulateMedia({ colorScheme: scheme });
27	    for (const f of ['index', 'preface', 'intro', 'overview', 'programs', 'lexical-structure', 'evaluation', 'types', 'notes', 'references']) {
28	      await p.goto(U + f + '.html');
29	      const w = await p.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
30	      const bg = await p.evaluate(() => getComputedStyle(document.body).backgroundColor);
31	      ok(w === 0, `${scheme} ${f}: no sideways scroll (${w}) bg ${bg}`);
32	    }
33	  }
34	  await p.emulateMedia({ colorScheme: 'light' });
35	  await p.goto(U + 'overview.html');
36	  const gutter = await p.evaluate(() => document.querySelector('.page').getBoundingClientRect().left);
37	  ok(gutter === 16, 'gutter 16px: ' + gutter);
38	  // Select
39	  await p.locator('#sec-programming-env button.sel').click();
40	  const sel = await p.evaluate(() => window.getSelection().toString());
41	  ok(sel.startsWith('2.1 The Fortress Programming Environment') && !sel.includes('Exports and Imports') && sel.includes('must contain exactly one component'), 'Select takes section 2.1 only: ' + sel.length + ' chars; starts ' + JSON.stringify(sel.slice(0, 60)));
42	  ok(!sel.includes('✎') && !sel.includes('Select'), 'selection has no button text');
43	  // notes: paragraph, code, heading
44	  const para = p.locator('#sec-overview-apis ~ p.nb').first();
45	  await para.locator('.addnote').click();
46	  await p.locator('.note-edit textarea').fill('Why are APIs program constructs?\nSecond line.');
47	  await p.locator('.note-edit button.primary').click();
48	  const code = p.locator('.fx[data-example="Executable"]');
49	  await code.locator('.addnote').click();
50	  await p.locator('.note-edit textarea').fill('varargs parameter: check the revival.');
51	  await p.locator('.note-edit button.primary').click();
52	  await p.locator('#sec-overview-aggregate .addnote').first().click();
53	  await p.locator('.note-edit textarea').fill('Heading note.');
54	  await p.locator('.note-edit button.primary').click();
55	  ok(await p.locator('.note-card').count() === 3, 'three note cards');
56	  ok(await p.locator('.has-note').count() === 3, 'three places marked');
57	  ok((await p.locator('nav.bar .count').textContent()) === '3', 'count in the bar');
58	  // place
59	  await p.evaluate(() => document.querySelector('#sec-overview-function-overloading').scrollIntoView({ behavior: 'instant' }));
60	  await p.mouse.wheel(0, 300);
61	  await p.waitForTimeout(900);
62	  const place = await p.evaluate(() => JSON.parse(localStorage.getItem('fortress-spec.place.v1')));
63	  console.log('place', JSON.stringify(place.pages.overview));
64	  await p.screenshot({ path: path.join(SHOTS, 'spec-reader-light.png') });
65	  await p.goto(U + 'overview.html');
66	  await p.waitForTimeout(300);
67	  ok(await p.locator('.note-card').count() === 3, 'after reload: three note cards');
68	  ok(await p.locator('.resume').count() === 1, 'after reload: resume banner: ' + (await p.locator('.resume').innerText()).replace(/\n/g, ' | '));
69	  ok(await p.locator('details.chapter-notes summary').innerText() === 'Your notes in this chapter: 3', 'chapter list of notes');
70	  await p.locator('.resume a.act').click();
71	  await p.waitForTimeout(900);
72	  const y = await p.evaluate(a => document.getElementById(a).getBoundingClientRect().top, place.pages.overview.anchor);
73	  ok(y > 0 && y < 200, 'continue scrolls to the place (top ' + Math.round(y) + ')');
74	  // start page
75	  await p.goto(U + 'index.html');
76	  const cont = p.locator('#continue .resume');
77	  ok(await cont.count() === 1, 'start page offers: ' + (await cont.innerText()).replace(/\n/g, ' | '));
78	  const href = await cont.locator('a').getAttribute('href');
79	  ok(href === 'overview.html#' + place.pages.overview.anchor, 'continue link ' + href);
80	  ok(await p.locator('ul.chapters li.todo').count() > 40, 'unconverted chapters listed: ' + await p.locator('ul.chapters li.todo').count() + ', converted ' + await p.locator('ul.chapters li.done').count());
81	  // export
82	  await p.goto(U + 'notes.html');
83	  const text = await p.locator('#export-text').inputValue();
84	  console.log('----- export\n' + text + '-----');
85	  await p.locator('#copy-notes').click();
86	  await p.waitForTimeout(200);
87	  const clip = await p.evaluate(() => navigator.clipboard.readText());
88	  ok(clip === text, 'clipboard holds the export; status: ' + await p.locator('#export-status').innerText());
89	  const [dl] = await Promise.all([p.waitForEvent('download'), p.locator('#save-notes').click()]);
90	  const file = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'spec-notes-')), dl.suggestedFilename());
91	  await dl.saveAs(file);
92	  ok(fs.readFileSync(file, 'utf8') === text, 'saved file ' + dl.suggestedFilename());
93	  // link of a note leads to the place
94	  const link = /Link: (\S+)/.exec(text)[1];
95	  await p.goto(link.replace(PUBLIC, U));
96	  await p.waitForTimeout(500);
97	  const top = await p.evaluate(() => document.getElementById(decodeURIComponent(location.hash.slice(1))).getBoundingClientRect().top);
98	  ok(top > 40 && top < 120, 'exported link opens at the passage, below the bar (top ' + Math.round(top) + ')');
99	  // edit and delete
100	  await p.goto(U + 'notes.html');
101	  await p.locator('.note-card .meta button', { hasText: 'Edit' }).first().click();
102	  await p.locator('.note-edit textarea').fill('Edited note.');
103	  await p.locator('.note-edit button.primary').click();
104	  ok((await p.locator('.note-card .text').first().innerText()) === 'Edited note.', 'edit on the notes page');
105	  p.once('dialog', d => d.accept());
106	  await p.locator('.note-card .meta button.danger').first().click();
107	  ok(await p.locator('.note-card').count() === 2, 'delete leaves two');
108	  // cleared browser, then import
109	  await p.evaluate(() => localStorage.clear());
110	  await p.reload();
111	  ok(await p.locator('.note-card').count() === 0, 'cleared: no notes');
